candidates.raw:
    if ((sigma == NULL) || (shadow == NULL) || (switched == NULL)) {
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(sigma)) {
        shadow->x = 0.0;
        shadow->y = 0.0;
        shadow->z = 0.0;
        *switched = 0;
        return ADCS_E_NOT_FINITE;
    }

    double norm_sq = sigma->x * sigma->x + sigma->y * sigma->y + sigma->z * sigma->z;

    if (norm_sq > 1.0) {
        double inv_norm_sq = 1.0 / norm_sq;
        shadow->x = -sigma->x * inv_norm_sq;
        shadow->y = -sigma->y * inv_norm_sq;
        shadow->z = -sigma->z * inv_norm_sq;
        *switched = 1;
    } else {
        shadow->x = sigma->x;
        shadow->y = sigma->y;
        shadow->z = sigma->z;
        *switched = 0;
    }

    return ADCS_OK;
}

