    if (sigma == NULL || shadow == NULL || switched == NULL) {
        return ADCS_E_NULL;
    }

    if (!isfinite(sigma->x) || !isfinite(sigma->y) || !isfinite(sigma->z)) {
        *shadow = (adcs_vec3_t){0.0, 0.0, 0.0};
        *switched = 0;
        return ADCS_E_NOT_FINITE;
    }

    double norm_sq = sigma->x * sigma->x + sigma->y * sigma->y + sigma->z * sigma->z;

    if (norm_sq > 1.0) {
        double scale = -1.0 / norm_sq;
        shadow->x = sigma->x * scale;
        shadow->y = sigma->y * scale;
        shadow->z = sigma->z * scale;
        *switched = 1;
    } else {
        *shadow = *sigma;
        *switched = 0;
    }

    return ADCS_OK;
}

